+static pid_t fork_waiting_child(int pipefd[2])
+{
+	pid_t pid;
+
+	if (pipe(pipefd))
+		ksft_exit_fail_perror("pipe");
+	pid = fork();
+	if (pid < 0)
+		ksft_exit_fail_perror("fork");
+	if (!pid) {
+		char byte;
+
+		close(pipefd[1]);
+		while (read(pipefd[0], &byte, 1) < 0 && errno == EINTR)
+			;
+		_exit(0);
+	}
+	close(pipefd[0]);
+	return pid;
+}
